package dev.starworld.runtime;

import dev.starworld.disaster.DisasterResponseService;
import dev.starworld.disaster.DisasterState.Response;
import dev.starworld.domain.WorldState.*;
import dev.starworld.integration.CoreBridge;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import org.bukkit.Server;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class DisasterControllerTest {
    private static final class Fixture {
        final JavaPlugin plugin=mock(JavaPlugin.class);final Server server=mock(Server.class);final WorldRuntime runtime=mock(WorldRuntime.class);final CoreBridge core=mock(CoreBridge.class);final DisasterResponseService service=mock(DisasterResponseService.class);final Player player=mock(Player.class);
        final UUID actor=UUID.randomUUID(),anchor=UUID.randomUUID();final CoreCity city=new CoreCity(UUID.randomUUID(),UUID.randomUUID(),"城市","国家",1,"fixture");final EventState event=new EventState("drought",10,13,15);
        final CityView view=new CityView(city.cityId(),city.nationId(),city.cityName(),"agrarian",9,Map.of(),List.of(),event,"");final DisasterController controller;
        Fixture(){when(plugin.getServer()).thenReturn(server);when(server.isPrimaryThread()).thenReturn(true);when(player.isOnline()).thenReturn(true);when(player.hasPermission("starworld.use")).thenReturn(true);when(player.getUniqueId()).thenReturn(actor);when(runtime.playerCity(player)).thenReturn(Optional.of(city));when(core.city(city.cityId())).thenReturn(Optional.of(city));when(runtime.manage(player,city.cityId())).thenReturn(true);when(runtime.currentPeriod()).thenReturn(10L);when(runtime.verifiedBuildings(view)).thenReturn(Set.of(anchor));when(runtime.open(city)).thenReturn(CompletableFuture.completedFuture(view));controller=new DisasterController(plugin,runtime,core,service);}
        @SuppressWarnings("unchecked") void immediate(){when(runtime.async(any())).thenAnswer(call->{try{return CompletableFuture.completedFuture(((WorldRuntime.Work<?>)call.getArgument(0)).run());}catch(Exception error){return CompletableFuture.failedFuture(error);}});doAnswer(call->{CompletableFuture<?> result=call.getArgument(1);((Consumer<Object>)call.getArgument(2)).accept(result.join());return null;}).when(runtime).reply(any(),any(),any());}
    }
    @Test void captureIsMainThreadOnlyAndUsesLivePermissionNationAndVerifiedAnchors(){Fixture f=new Fixture();var capture=f.controller.capture(f.player,f.city,f.view);assertEquals(f.city,capture.city());assertEquals(f.event,capture.event());assertEquals(10,capture.period());assertEquals(Set.of(f.anchor),capture.verified());assertEquals(f.actor.toString(),capture.actor());assertThrows(UnsupportedOperationException.class,()->capture.verified().add(UUID.randomUUID()));when(f.server.isPrimaryThread()).thenReturn(false);assertThrows(IllegalStateException.class,()->f.controller.capture(f.player,f.city,f.view));verify(f.runtime,times(1)).verifiedBuildings(f.view);verifyNoInteractions(f.service);}
    @Test void captureRejectsOfflineRevokedOrConqueredAuthority(){Fixture f=new Fixture();when(f.player.isOnline()).thenReturn(false);assertThrows(IllegalArgumentException.class,()->f.controller.capture(f.player,f.city,f.view));when(f.player.isOnline()).thenReturn(true);when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(false);assertThrows(IllegalArgumentException.class,()->f.controller.capture(f.player,f.city,f.view));when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(true);CoreCity conquered=new CoreCity(f.city.cityId(),UUID.randomUUID(),"城市","占领国",1,"changed");when(f.core.city(f.city.cityId())).thenReturn(Optional.of(conquered));assertThrows(IllegalArgumentException.class,()->f.controller.capture(f.player,f.city,f.view));verify(f.runtime,never()).verifiedBuildings(any());verifyNoInteractions(f.service);}
    @Test void respondChecksManagerBeforeStartingAnyRead(){Fixture f=new Fixture();when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(false);assertTrue(f.controller.execute(f.player,new String[]{"disaster","respond","drought_irrigation",UUID.randomUUID().toString()}));verify(f.player).sendMessage(contains("城市管理权限"));verify(f.runtime,never()).open(any());verify(f.runtime,never()).async(any());verifyNoInteractions(f.service);}
    @Test void responseCallbackRechecksMembershipAfterAsyncReadBeforeAnyWrite(){Fixture f=new Fixture();f.immediate();when(f.runtime.playerCity(f.player)).thenReturn(Optional.of(f.city),Optional.empty());f.controller.execute(f.player,new String[]{"disaster","respond","drought_irrigation",UUID.randomUUID().toString()});verify(f.player).sendMessage(contains("请先加入"));verify(f.runtime,never()).async(any());verify(f.runtime,never()).verifiedBuildings(any());verifyNoInteractions(f.service);}
    @Test void responseCallbackRechecksRevokedManagerAfterAsyncReadBeforeAnyWrite(){Fixture f=new Fixture();f.immediate();when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(true,false);f.controller.execute(f.player,new String[]{"disaster","respond","drought_irrigation",UUID.randomUUID().toString()});verify(f.player).sendMessage(contains("城市管理权限"));verify(f.runtime,never()).async(any());verify(f.runtime,never()).verifiedBuildings(any());verifyNoInteractions(f.service);}
    @Test void responsePreservesTheCallerRequestIdAndCapturedEventIntoTheStorageRequest()throws Exception{Fixture f=new Fixture();f.immediate();UUID requestId=UUID.randomUUID();Response receipt=mock(Response.class);when(receipt.requestId()).thenReturn(requestId);when(receipt.strategyId()).thenReturn("drought_irrigation");when(receipt.costs()).thenReturn(Map.of("minecraft:bread",12L));when(f.service.request(requestId,f.city,"drought_irrigation",10,Set.of(f.anchor),f.actor.toString(),f.event)).thenReturn(receipt);f.controller.execute(f.player,new String[]{"disaster","respond","drought_irrigation",requestId.toString()});verify(f.service).request(requestId,f.city,"drought_irrigation",10,Set.of(f.anchor),f.actor.toString(),f.event);verify(f.player).sendMessage(contains(requestId.toString()));verify(f.runtime).verifiedBuildings(f.view);}
    @Test void unrelatedCommandsAndInvalidPagesDoNotReachStorage(){Fixture f=new Fixture();assertFalse(f.controller.execute(f.player,new String[]{"history"}));assertTrue(f.controller.execute(f.player,new String[]{"disaster","history","0"}));verify(f.player).sendMessage(contains("页码"));verify(f.runtime,never()).async(any());verifyNoInteractions(f.service);}
    @Test void configuredSmallPageLimitStillAllowsStatusAndHistoryPagination()throws Exception{Fixture f=new Fixture();f.immediate();var configuration=mock(dev.starworld.disaster.DisasterResponseDefinitions.class);var data=mock(dev.starworld.disaster.DisasterState.Definitions.class);when(data.maxPage()).thenReturn(1);when(configuration.data()).thenReturn(data);when(f.service.configuration()).thenReturn(configuration);when(f.service.responses(f.city.cityId(),1,1)).thenReturn(List.of());when(f.service.history(f.city.cityId(),1,2)).thenReturn(List.of());f.controller.execute(f.player,new String[]{"disaster","status","2"});f.controller.execute(f.player,new String[]{"disaster","history","3"});verify(f.service).responses(f.city.cityId(),1,1);verify(f.service).history(f.city.cityId(),1,2);}
    @Test void guiSubmissionPreservesThePreviewEventEvenWhenFreshStorageContainsAReplacement()throws Exception{Fixture f=new Fixture();f.immediate();EventState replacement=new EventState("drought",11,14,16);CityView replaced=new CityView(f.city.cityId(),f.city.nationId(),"城市","agrarian",9,Map.of(),List.of(),replacement,"");when(f.runtime.open(f.city)).thenReturn(CompletableFuture.completedFuture(replaced));when(f.runtime.verifiedBuildings(replaced)).thenReturn(Set.of(f.anchor));UUID request=UUID.randomUUID();Response receipt=mock(Response.class);when(receipt.requestId()).thenReturn(request);when(receipt.costs()).thenReturn(Map.of());when(f.service.request(request,f.city,"drought_irrigation",10,Set.of(f.anchor),f.actor.toString(),f.event)).thenReturn(receipt);List<Response> complete=new ArrayList<>();f.controller.respondFromPreview(f.player,f.city,"drought_irrigation",request,f.event,complete::add);verify(f.service).request(request,f.city,"drought_irrigation",10,Set.of(f.anchor),f.actor.toString(),f.event);verify(f.service,never()).request(eq(request),any(),anyString(),anyLong(),anySet(),anyString(),eq(replacement));assertEquals(List.of(receipt),complete);}
    @Test void guiSubmissionRechecksRevokedManagementAfterTheStorageRead(){Fixture f=new Fixture();f.immediate();when(f.runtime.manage(f.player,f.city.cityId())).thenReturn(true,false);assertThrows(IllegalArgumentException.class,()->f.controller.respondFromPreview(f.player,f.city,"drought_irrigation",UUID.randomUUID(),f.event,response->fail("Revoked GUI submission must not complete")));verify(f.runtime,never()).async(any());verify(f.runtime,never()).verifiedBuildings(any());verifyNoInteractions(f.service);}
    @Test void guiSubmissionRechecksRevokedUsePermissionAfterTheStorageRead(){Fixture f=new Fixture();f.immediate();when(f.player.hasPermission("starworld.use")).thenReturn(true,false);assertThrows(IllegalArgumentException.class,()->f.controller.respondFromPreview(f.player,f.city,"drought_irrigation",UUID.randomUUID(),f.event,response->fail("Revoked GUI submission must not complete")));verify(f.runtime,never()).async(any());verify(f.runtime,never()).verifiedBuildings(any());verifyNoInteractions(f.service);}
}
